import{_ as l,l as r,o as e,c as d,v as o,p as n,x as t,d as s,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"机台对机台套刻","description":"","frontmatter":{"title":"机台对机台套刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-to-tool-overlay.md","filePath":"litho/tool-to-tool-overlay.md","lastUpdated":1789023840000}'),p={name:"litho/tool-to-tool-overlay.md"};function E(_,a,A,B,m,u){const i=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="机台对机台套刻" tabindex="-1">机台对机台套刻 <a class="header-anchor" href="#机台对机台套刻" aria-label="Permalink to &quot;机台对机台套刻&quot;">​</a></h1><div class="epigraph"><p>同一套版，A 机曝栅、B 机曝切线，套刻指纹是两台机器的差，不是单机规格的均方根能代办的。</p><footer>—— 对照 dedicated chuck / tool dedication 与 overlay matching 的公开讨论</footer></div><p><a href="/litho/wafer-distortion-stress">上一课</a>给出工艺弯月。缺口是混流：量产不会单机。<a href="/litho/tool-matching">机台匹配</a> 已写扫描机指纹匹配；本课钉<strong>层间套刻的机台对</strong>，不重写照明瞳匹配全文。厂级数据如何把这些环连起来，留给[下一课](/litho/fab-data-loop）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>层间 overlay = 本层机台指纹 − 参考层机台指纹 + 工艺 + 版图。单机都在规格内，差值可以超关键对规格。策略：关键对专用机台/卡盘（dedication）、或把匹配残差压进预算并在 APC 里存「机台对」指纹。混用无匹配的 EUV 与浸没更严。</p><p>缺口是<strong>对的矩阵</strong>，不是单机校准。N 台机的关键对有 \\(N\\times N\\) 种差，全部开放则匹配实验爆炸。实务是聚类：匹配到参考机，或关键层锁定子集。</p><h3 id="卡盘与镜头要分账" tabindex="-1">卡盘与镜头要分账 <a class="header-anchor" href="#卡盘与镜头要分账" aria-label="Permalink to &quot;卡盘与镜头要分账&quot;">​</a></h3><p>同一机台换卡盘，翘曲吸平变；镜头指纹相对稳。匹配要以卡盘为对象，而不是只写机台序号。Twinscan 双台本身就要当两个卡盘匹配。</p><p><span class="marginnote">APC 状态必须用 (机台, 卡盘, 层对) 做键。串错键，补偿会加在错误的差上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>匹配：用同一批或专用匹配片在机台对上曝参考层与本层（或测扫描机网格差）。预算：匹配残差占 overlay 分账。调度：MES 对关键对限制机台集合。与计量匹配：套刻机也要进同一尺度，否则机台差被计量差污染。</p><p>dedication 名单要短而硬：关键对只允许已匹配的子集，紧急混机必须走加密计量和临时指纹，而不是默默借用邻机状态。公开的 overlay matching / chuck dedication 讨论，核心就是这张矩阵的稀疏化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指纹 \\(F_i(x,y)\\)。层对 \\((i,j)\\) 的系统 overlay 含 \\(F_j-F_i\\)。dedication 令 \\(i=j\\) 的硬件相关部分相消，工艺项仍在。匹配把 \\(F_j-F_i\\) 降到残差。APC 存 \\(\\widehat{F_j-F_i}\\)。换机等于换模型键，应重置或加载对应键，与 R2R 事件规则相同。</p>',14)),(e(),n(c,null,{default:t(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9C%BA%E5%8F%B0%20A%20%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DIFF%5B%22A%E2%88%92B%20%E5%B7%AE%22%5D%0A%20%20B%5B%22%E6%9C%BA%E5%8F%B0%20B%20%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DIFF%0A%20%20DIFF%20--%3E%20BUD%5B%22%E5%A5%97%E5%88%BB%E5%88%86%E8%B4%A6%22%5D%0A%20%20DED%5B%22%E5%85%B3%E9%94%AE%E5%AF%B9%E9%94%81%E5%AE%9A%E5%AD%90%E9%9B%86%22%5D%20--%3E%20DIFF%0A%20%20MATCH%5B%22%E5%8C%B9%E9%85%8D%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20BUD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>层间看见的是指纹差。APC 键含机台与卡盘；串错键等于把补偿加在错误的差上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重复扫描机光学匹配细节。不把某厂 dedication 政策当 SEMI 强制。本课不写价格与机时费。</p><p>后课默认：关键套刻按机台–卡盘对管理。下一课把 APC、SPC、分派接到厂级数据系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层间套刻看见机台指纹差；dedication 或匹配残差分账。</li><li>APC 键含机台与卡盘。</li><li>计量匹配必须同步，以免假机台差。</li><li>出处：overlay matching / chuck dedication 公开讨论；ASML 匹配公开论述。</li></ul>',6))])}const P=l(p,[["render",E]]);export{D as __pageData,P as default};
